import{at as e,it as t,t as n,yt as r}from"./chunks/framework.DJ1YMEMN.js";var i=JSON.parse(`{"title":"Multiple Frameworks on One Page","description":"Learn how to use more than one framework on the same page with WarpDrive by importing @warp-drive/alien-signals/install before each framework's install entry point.","frontmatter":{"title":"Multiple Frameworks on One Page","description":"Learn how to use more than one framework on the same page with WarpDrive by importing @warp-drive/alien-signals/install before each framework's install entry point."},"headers":[],"relativePath":"guides/faq/multiple-frameworks.md","filePath":"guides/faq/multiple-frameworks.md"}`),a={name:`guides/faq/multiple-frameworks.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="can-i-use-multiple-frameworks-on-one-page-for-instance-ember-and-react" tabindex="-1">Can I use multiple frameworks on one page (for instance Ember and React)? <a class="header-anchor" href="#can-i-use-multiple-frameworks-on-one-page-for-instance-ember-and-react" aria-label="Permalink to “Can I use multiple frameworks on one page (for instance Ember and React)?”">​</a></h1><p>Yes. One <strong><em>Warp</em>Drive</strong> store can drive components from more than one framework on the same page. Import <code>@warp-drive/alien-signals/install</code> first, then each framework&#39;s <code>install</code> entry point:</p><div class="language-ts"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/alien-signals/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/ember/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@warp-drive/react/install&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Each framework generally only re-renders in response to its own signals implementation: Ember re-renders for its autotracking tags, and React components re-render for the signals that <code>@warp-drive/react</code> subscribes them to. On its own, each framework&#39;s <code>install</code> entry point configures <strong><em>Warp</em>Drive</strong> to use that framework&#39;s signals alone.</p><p><a href="/pr-preview/pr-11389/api/@warp-drive/alien-signals/"><code>@warp-drive/alien-signals</code></a> solves this. Its <code>install</code> entry point configures a signals graph that the frameworks imported after it add their signals to. It also provides the memos for all of them, so memoized values update in every framework. Import it first: importing it after another framework&#39;s <code>install</code> entry point throws.</p><div class="tip custom-block"><p class="custom-block-title">Derivations only track WarpDrive&#39;s signals</p><p>With <code>@warp-drive/alien-signals/install</code>, memoized values such as <a href="/pr-preview/pr-11389/guides/the-manual/schemas/derivations">derived fields</a> only recompute when a signal <strong><em>Warp</em>Drive</strong> manages changes. If a derivation reads state that only a framework tracks, such as an Ember <code>@tracked</code> property or a React <code>useState</code> value, it keeps returning its cached value when that state changes. Keep the state a derivation reads in <strong><em>Warp</em>Drive</strong>, for instance as a field on the resource it derives from.</p></div><p>For a complete example with Ember and React, see <a href="/pr-preview/pr-11389/guides/the-manual/cookbook/multiple-frameworks-on-one-page">Using Ember and React on the Same Page</a>.</p>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};